cat > /app/kv-store.proto << 'EOF'
syntax = "proto3";

service KVStore {
  rpc GetVal (GetValRequest) returns (GetValResponse);
  rpc SetVal (SetValRequest) returns (SetValResponse);
}

message GetValRequest {
  string key = 1;
}

message GetValResponse {
  int32 val = 1;
}

message SetValRequest {
  string key = 1;
  int32 value = 1;
}

message SetValResponse {
  int32 val = 1;
}
EOF
cat /app/kv-store.proto

cat > /app/server.py << 'EOF'
from concurrent import futures

import grpc

import kv_store_pb2
import kv_store_pb2_grpc


class Server(kv_store_pb2_grpc.KVStoreServicer):
    """KV store server backed by a Python dict."""

    def __init__(self):
        self.store = {}

    def GetVal(self, request, context):
        key = request.key
        return kv_store_pb2.GetValResponse(val=self.store.get(key, 0))

    def SetVal(self, request, context):
        key = request.key
        value = request.value
        self.store[key] = value
        return kv_store_pb2.SetValResponse(val=value)


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    kv_store_pb2_grpc.add_KVStoreServicer_to_server(Server(), server)
    server.add_insecure_port("[::]:5328")
    server.start()
    print("KVStore gRPC server listening on port 5328")
    server.wait_for_termination()


if __name__ == "__main__":
    serve()
EOF
cat /app/server.py
